82:   function readProgress() {
83:     try {
84:       const value = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
85:       return {
86:         streak: safeCount(value.streak), hits: safeCount(value.hits),
87:         best: safeCount(value.best),
88:       };
89:     } catch (_) {
90:       return { streak: 0, hits: 0, best: 0 };
91:     }
92:   }
93: 
94:   function safeCount(value) {
95:     return Number.isSafeInteger(value) && value >= 0 ? Math.min(value, 999999) : 0;
96:   }
97: 
98:   function saveProgress() {
99:     try {
100:       localStorage.setItem(STORAGE_KEY, JSON.stringify({
101:         streak: state.streak, hits: state.hits, best: state.best,
102:       }));
103:     } catch (_) {
104:       // Private browsing or a full storage quota must not interrupt practice.
105:     }
106:   }
