108:   const MIN_TAP_INTERVAL = 250;
109:   const MAX_TAP_INTERVAL = 1500;
110:   const LONG_PAUSE = 2200;
111:   const OUTLIER_TOLERANCE = 0.2;
112: 
113:   function handleTap() {
114:     const now = performance.now();
115:     const hadPreviousTap = state.lastTapAt !== null;
116:     pulseTapButton();
117:     if (state.soundOn) resumeAudio();
118: 
119:     if (state.lastTapAt !== null) {
120:       const interval = now - state.lastTapAt;
121:       if (interval > LONG_PAUSE) {
122:         state.intervals = [];
123:         state.pendingIntervals = [];
124:       } else if (interval >= MIN_TAP_INTERVAL && interval <= MAX_TAP_INTERVAL) {
125:         acceptTapInterval(interval);
126:       } else {
127:         state.pendingIntervals = [];
128:       }
129:     }
130:     state.lastTapAt = now;
131: 
132:     if (!state.bpm) {
133:       ui.tempoCaption.textContent = hadPreviousTap
134:         ? 'Seguí tocando para fijar el pulso'
135:         : 'Tocá al ritmo de tu base';
136:     }
137:     if (state.vibrationOn) requestTapVibration();
138:   }
139: 
140:   function acceptTapInterval(interval) {
141:     const baseline = median(state.intervals);
142:     if (!baseline || Math.abs(interval - baseline) <= baseline * OUTLIER_TOLERANCE) {
143:       state.intervals.push(interval);
144:       state.intervals = state.intervals.slice(-6);
145:       state.pendingIntervals = [];
146:     } else {
147:       const pendingBaseline = median(state.pendingIntervals);
148:       if (!pendingBaseline || Math.abs(interval - pendingBaseline) > pendingBaseline * OUTLIER_TOLERANCE) {
149:         state.pendingIntervals = [interval];
150:       } else {
151:         state.pendingIntervals.push(interval);
152:         if (state.pendingIntervals.length >= 2) {
153:           state.intervals = state.pendingIntervals.slice(-6);
154:           state.pendingIntervals = [];
155:         }
156:       }
157:     }
158: 
159:     if (!state.intervals.length) return;
160:     const previousBpm = state.bpm;
161:     const estimate = estimateBpm(state.intervals);
162:     state.bpm = estimate;
163:     ui.bpm.textContent = String(estimate);
164:     ui.tempoCaption.textContent = `Pulso estimado · ${effectiveTempo()} BPM de práctica`;
165:     setTempoReady(true);
166:     if (state.running && previousBpm !== estimate) adjustClockTempo();
167:     else startClock();
168:   }
169: 
170:   function median(values) {
171:     if (!values.length) return null;
172:     const ordered = [...values].sort((a, b) => a - b);
173:     const middle = Math.floor(ordered.length / 2);
174:     return ordered.length % 2 ? ordered[middle] : (ordered[middle - 1] + ordered[middle]) / 2;
175:   }
176: 
177:   function estimateBpm(intervals) {
178:     const average = intervals.reduce((sum, value) => sum + value, 0) / intervals.length;
179:     return Math.max(40, Math.min(240, Math.round(60000 / average)));
180:   }
181: 
182:   function effectiveTempo() {
183:     return state.bpm ? state.bpm * (state.mode === 'doble' ? 2 : 1) : 0;
184:   }
185: 
186:   function setTempoReady(ready) {
187:     ui.tempoStatus.classList.toggle('running', ready && state.running);
188:     ui.tempoStatus.lastChild.textContent = ready ? (state.running ? 'EN MARCHA' : 'LISTO') : 'ESPERANDO';
189:   }
190: 
191:   function updateClockExplanation() {
192:     const modeFactor = state.mode === 'doble' ? 2 : 1;
193:     const hitsPerBeat = state.subdivision * modeFactor;
194:     const hitLabel = hitsPerBeat === 1 ? 'golpe' : 'golpes';
195:     ui.clockExplanation.textContent = `Cuenta: subdivisión ×${state.subdivision} × dinámica ×${modeFactor} = ${hitsPerBeat} ${hitLabel} por pulso base; ${hitsPerBeat * 4} por compás 4/4.`;
196:   }
197: 
198:   function clockGrid(tick) {
199:     const divisions = state.subdivision * (state.mode === 'doble' ? 2 : 1);
200:     return {
201:       divisions,
202:       stepMs: 60000 / state.bpm / divisions,
203:       beat: Math.floor(tick / divisions) % 4,
204:       isAccent: tick % divisions === 0,
205:     };
206:   }
207: 
208:   function startClock() {
209:     if (!state.bpm || state.running) return;
210:     state.running = true;
211:     state.generation += 1;
212:     state.tickNumber = 0;
213:     state.lastTickNumber = -1;
214:     state.lastTickAt = null;
215:     state.clockStepMs = clockGrid(0).stepMs;
216:     state.nextTickAt = performance.now() + 70;
217:     setTempoReady(true);
218:     ui.tempoCaption.textContent = `Pulso estimado · ${effectiveTempo()} BPM de práctica`;
219:     scheduleLoop(state.generation);
220:   }
221: 
222:   function clearClockTimers() {
223:     window.clearTimeout(state.timer);
224:     state.tickTimerIds.forEach((id) => window.clearTimeout(id));
225:     state.tickTimerIds.clear();
226:   }
227: 
228:   function adjustClockTempo() {
229:     const now = performance.now();
230:     const oldStepMs = state.clockStepMs || clockGrid(0).stepMs;
231:     const phase = state.lastTickAt === null
232:       ? 0
233:       : Math.max(0, Math.min(1, (now - state.lastTickAt) / oldStepMs));
234:     state.generation += 1;
235:     clearClockTimers();
236:     state.clockStepMs = clockGrid(0).stepMs;
237:     if (state.lastTickNumber < 0) {
238:       state.tickNumber = 0;
239:       state.nextTickAt = now + 70;
240:     } else {
241:       state.tickNumber = state.lastTickNumber + 1;
242:       state.nextTickAt = now + Math.max(8, state.clockStepMs * (1 - phase));
243:     }
244:     scheduleLoop(state.generation);
245:   }
246: 
247:   const CLOCK_LOOKAHEAD_MS = 100;
248:   const CLOCK_LOOP_MS = 25;
249:   const MAX_CLOCK_LATENESS_MS = 50;
250: 
251:   function scheduleLoop(generation) {
252:     if (!state.running || generation !== state.generation) return;
253:     const now = performance.now();
254:     if (state.nextTickAt < now - MAX_CLOCK_LATENESS_MS) {
255:       clearClockTimers();
256:       state.tickNumber = Math.max(0, state.lastTickNumber + 1);
257:       state.nextTickAt = now + 8;
258:     }
259:     while (state.nextTickAt <= now + CLOCK_LOOKAHEAD_MS) {
260:       const scheduledAt = state.nextTickAt;
261:       const tick = state.tickNumber++;
262:       const grid = clockGrid(tick);
263:       queueTick(scheduledAt, tick, grid, generation);
264:       if (state.soundOn) scheduleClick(scheduledAt, grid.isAccent);
265:       state.nextTickAt += grid.stepMs;
266:     }
267:     state.timer = window.setTimeout(() => scheduleLoop(generation), CLOCK_LOOP_MS);
268:   }
269: 
270:   function queueTick(time, tick, grid, generation) {
271:     const delay = Math.max(0, time - performance.now());
272:     const id = window.setTimeout(() => {
273:       state.tickTimerIds.delete(id);
274:       if (!state.running || generation !== state.generation) return;
275:       if (tick <= state.lastTickNumber) return;
276:       if (performance.now() - time > Math.min(state.clockStepMs, MAX_CLOCK_LATENESS_MS)) return;
277:       state.lastTickNumber = tick;
278:       state.lastTickAt = time;
279:       renderBeat(grid.beat, grid.isAccent);
280:       if (grid.isAccent) onMainBeat(grid.beat);
281:     }, delay);
282:     state.tickTimerIds.add(id);
283:   }
284: 
285:   function renderBeat(beat, isAccent) {
286:     ui.beatBoxes.forEach((box, index) => {
287:       box.classList.toggle('active', index === beat && isAccent);
288:       box.classList.toggle('sub-beat', index === beat && !isAccent);
289:     });
290:   }
291: 
292:   function onMainBeat(beat) {
293:     if (beat === 0) {
294:       state.roundNumber += 1;
295:       state.currentPrompt = choosePrompt(state.mode);
296:       state.rhymeRevealed = false;
297:       state.hitThisRound = false;
298:       ui.hit.disabled = true;
299:       ui.round.textContent = `RONDA ${String(state.roundNumber).padStart(2, '0')}`;
300:       ui.promptLabel.textContent = state.mode === 'esdrujulas' ? 'CONCEPTO · ACENTO EN LA ANTEPENÚLTIMA' : 'CONCEPTO · DOBLE TEMPO';
301:       ui.promptIndex.textContent = `#${String(state.roundNumber).padStart(2, '0')}`;
302:       ui.promptWord.textContent = state.currentPrompt.word;
303:       ui.promptWord.classList.remove('pop');
304:       void ui.promptWord.offsetWidth;
305:       ui.promptWord.classList.add('pop');
306:       ui.promptHint.textContent = state.currentPrompt.hint;
307:       ui.instruction.textContent = state.mode === 'doble' ? 'Doblá las sílabas; el remate llega en el pulso 3.' : 'En el 1, agarrá el concepto. En el 3, buscá el remate.';
308:       showEmptyRhymes();
309:     }
310:     if (beat === 2 && state.currentPrompt && !state.rhymeRevealed) revealRhymes();
311:   }
312: 
313:   function choosePrompt(mode) {
314:     const choices = PROMPTS[mode].filter((item) => item !== state.currentPrompt);
315:     return choices[Math.floor(Math.random() * choices.length)] || PROMPTS[mode][0];
316:   }
317: 
318:   function showEmptyRhymes() {
319:     ui.rhymeList.replaceChildren(...Array.from({ length: 4 }, () => {
320:       const chip = document.createElement('span');
321:       chip.className = 'rhyme-chip empty-chip';
322:       chip.textContent = '—';
323:       return chip;
324:     }));
325:     ui.revealNote.textContent = 'APARECE EN EL TIEMPO 3';
326:   }
327: 
328:   function revealRhymes() {
329:     state.rhymeRevealed = true;
330:     ui.rhymeList.replaceChildren(...state.currentPrompt.rhymes.map((word, index) => {
331:       const chip = document.createElement('span');
332:       chip.className = 'rhyme-chip';
333:       chip.textContent = word;
334:       chip.style.transitionDelay = `${index * 45}ms`;
335:       requestAnimationFrame(() => chip.classList.add('visible'));
336:       return chip;
337:     }));
338:     ui.revealNote.textContent = '¡REMATE A TU MANERA!';
339:     ui.hit.disabled = false;
340:   }
341: 
342:   function renderEmptyPrompt() {
343:     ui.round.textContent = 'RONDA 01';
344:     ui.promptLabel.textContent = 'TU CONCEPTO';
345:     ui.promptIndex.textContent = '#01';
346:     ui.promptWord.textContent = 'LISTA';
347:     ui.promptHint.textContent = 'Marcá cuatro pulsos para empezar';
348:     ui.instruction.textContent = 'En el 1, agarrá el concepto. En el 3, buscá el remate.';
349:     ui.hit.disabled = true;
350:     showEmptyRhymes();
351:   }
352: 
353:   function confirmHit() {
354:     if (!state.rhymeRevealed || state.hitThisRound) return;
355:     state.hitThisRound = true;
356:     state.streak += 1;
357:     state.hits += 1;
358:     state.best = Math.max(state.best, state.streak);
359:     updateStats();
360:     saveProgress();
361:     ui.hit.disabled = true;
362:     ui.hit.innerHTML = 'REMATE GUARDADO <span>✓</span>';
363:     window.setTimeout(() => { ui.hit.innerHTML = '¡LA EMBOQUÉ! <span>↗</span>'; }, 1100);
364:     showToast('Una más para la racha. ¡Buen remate!');
365:   }
366: 
367:   function updateStats() {
368:     ui.streak.textContent = String(state.streak);
369:     ui.hits.textContent = String(state.hits);
370:     ui.best.textContent = String(state.best);
371:   }
372: 
373:   function setMode(mode) {
374:     if (!PROMPTS[mode]) return;
375:     state.mode = mode;
376:     document.body.classList.toggle('mode-double', mode === 'doble');
377:     ui.modeButtons.forEach((button) => {
378:       const active = button.dataset.mode === mode;
379:       button.classList.toggle('active', active);
380:       button.setAttribute('aria-pressed', String(active));
381:     });
382:     updateClockExplanation();
383:     if (state.bpm) ui.tempoCaption.textContent = `Pulso estimado · ${effectiveTempo()} BPM de práctica`;
384:     restartClockPhase();
385:   }
386: 
387:   function restartClockPhase() {
388:     if (!state.running) return;
389:     state.generation += 1;
390:     clearClockTimers();
391:     state.tickNumber = 0;
392:     state.lastTickNumber = -1;
393:     state.lastTickAt = null;
394:     state.clockStepMs = clockGrid(0).stepMs;
395:     state.nextTickAt = performance.now() + 70;
396:     scheduleLoop(state.generation);
397:   }
398: 
399:   function stopClock() {
400:     state.running = false;
401:     state.generation += 1;
402:     clearClockTimers();
403:     ui.beatBoxes.forEach((box) => box.classList.remove('active', 'sub-beat'));
404:     setTempoReady(Boolean(state.bpm));
405:   }
406: 
407:   function resetSession() {
408:     stopClock();
409:     state.lastTapAt = null;
410:     state.intervals = [];
411:     state.pendingIntervals = [];
412:     state.bpm = null;
413:     state.roundNumber = 0;
414:     state.currentPrompt = null;
415:     state.rhymeRevealed = false;
416:     state.hitThisRound = false;
417:     state.streak = 0;
418:     state.hits = 0;
419:     ui.bpm.textContent = '—';
420:     ui.tempoCaption.textContent = 'Tocá al ritmo de tu base';
421:     ui.hit.innerHTML = '¡LA EMBOQUÉ! <span>↗</span>';
422:     renderEmptyPrompt();
423:     updateStats();
424:     saveProgress();
425:     showToast('Sesión reiniciada. El récord queda guardado.');
426:   }
427: 
428:   function pulseTapButton() {
429:     ui.tap.classList.add('pulse');
430:     window.setTimeout(() => ui.tap.classList.remove('pulse'), 110);
431:   }
432: 
433:   function toggleSound() {
434:     state.soundOn = !state.soundOn;
435:     if (state.soundOn) resumeAudio();
436:     updateSoundButton();
437:     showToast(state.soundOn ? 'Metrónomo sonoro activado.' : 'Metrónomo sonoro silenciado.');
438:   }
439: 
440:   function updateSoundButton() {
441:     ui.sound.classList.toggle('active', state.soundOn);
442:     ui.sound.setAttribute('aria-pressed', String(state.soundOn));
443:     ui.sound.setAttribute('aria-label', state.soundOn ? 'Silenciar metrónomo' : 'Activar metrónomo sonoro');
444:     ui.sound.title = state.soundOn ? 'Silenciar metrónomo' : 'Activar metrónomo sonoro';
445:   }
446: 
447:   function toggleVibration() {
448:     if (typeof navigator.vibrate !== 'function') return;
449:     state.vibrationOn = !state.vibrationOn;
450:     updateVibrationButton();
451:     showToast(state.vibrationOn
452:       ? 'Vibración solicitada solo en cada tap manual.'
453:       : 'Vibración desactivada.');
454:   }
455: 
456:   function updateVibrationButton() {
457:     const supported = typeof navigator.vibrate === 'function';
458:     ui.vibration.disabled = !supported;
459:     ui.vibration.classList.toggle('active', supported && state.vibrationOn);
460:     ui.vibration.setAttribute('aria-pressed', String(supported && state.vibrationOn));
461:     const label = supported
462:       ? (state.vibrationOn ? 'Desactivar vibración en tap manual' : 'Activar vibración en cada tap manual')
463:       : 'Vibración no disponible en este dispositivo o navegador';
464:     ui.vibration.setAttribute('aria-label', label);
465:     ui.vibration.title = supported
466:       ? 'Solicitar vibración solo al tocar TAP (si el navegador lo permite)'
467:       : label;
468:   }
