470:   function requestTapVibration() {
471:     try {
472:       navigator.vibrate(8);
473:     } catch (_) {
474:       // Vibration is optional and must not interrupt manual Tap Tempo.
475:     }
476:   }
477: 
478:   function resumeAudio() {
479:     const AudioContextClass = window.AudioContext || window.webkitAudioContext;
480:     if (!AudioContextClass) return;
481:     try {
482:       if (!state.audio) state.audio = new AudioContextClass();
483:       if (state.audio.state === 'suspended') state.audio.resume();
484:     } catch (_) {
485:       // Visual timing remains available if Web Audio is unavailable.
486:     }
487:   }
488: 
489:   function scheduleClick(time, accented) {
490:     if (!state.audio || state.audio.state !== 'running') return;
491:     try {
492:       const oscillator = state.audio.createOscillator();
493:       const gain = state.audio.createGain();
494:       const start = state.audio.currentTime + Math.max(0, time - performance.now()) / 1000;
495:       oscillator.type = 'sine';
496:       oscillator.frequency.value = accented ? 880 : 590;
