cd /home/runner/work/Rapea_melelo/Rapea_melelo && cat > /tmp/opencode/rounds.js <<'JS'
async (page) => {
  await page.reload();
  const tap = page.locator('#tap-button');
  for (let i = 0; i < 6; i++) { await tap.click(); await page.waitForTimeout(500); }
  const samples = [];
  const start = Date.now();
  let lastRound = '';
  while (Date.now() - start < 16000) {
    const round = await page.locator('#round-count').textContent();
    if (round !== lastRound) {
      samples.push({ round, word: await page.locator('#prompt-word').textContent(), t: Date.now() - start });
      lastRound = round;
    }
    await page.waitForTimeout(60);
  }
  return samples;
}
JS
playwright-cli run-code --filename /tmp/opencode/rounds.js 2>&1 | head -3

cd /home/runner/work/Rapea_melelo/Rapea_melelo && cat > /tmp/opencode/deck3.js <<'JS'
async (page) => {
  await page.reload();
  const tap = page.locator('#tap-button');
  for (let i = 0; i < 6; i++) { await tap.click(); await page.waitForTimeout(500); }
  const rows = [];
  const start = Date.now();
  let lastRound = '';
  while (Date.now() - start < 45000) {
    const round = await page.locator('#round-count').textContent();
    if (round !== lastRound) {
      rows.push({ round: Number(round.replace(/\D/g, '')), word: await page.locator('#prompt-word').textContent() });
      lastRound = round;
    }
    await page.waitForTimeout(70);
  }
  const jumps = rows.filter((r, i) => i > 0 && r.round !== rows[i - 1].round + 1);
  const dupWindows = [];
  for (let i = 0; i + 7 < rows.length; i++) {
    const window = rows.slice(i, i + 8).map((r) => r.word);
    if (new Set(window).size !== window.length) dupWindows.push(window);
  }
  return { rounds: rows.length, words: rows.map((r) => r.word), jumps, dupWindows };
}
JS
playwright-cli run-code --filename /tmp/opencode/deck3.js 2>&1 | head -3; playwright-cli console 2>&1 | tail -3

cd /home/runner/work/Rapea_melelo/Rapea_melelo && git status --short; git log --oneline -3; cat > /tmp/opencode/final2.js <<'JS'
async (page) => {
  await page.setViewportSize({ width: 1280, height: 900 });
  await page.reload();
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  const tap = page.locator('#tap-button');
  for (let i = 0; i < 9; i++) { await tap.click(); await page.waitForTimeout(470); }
  await page.waitForTimeout(2200);
  await page.locator('[data-pattern="aabb"]').click();
  const out = {
    bpm: await page.locator('#bpm-value').textContent(),
    round: await page.locator('#round-count').textContent(),
    word: await page.locator('#prompt-word').textContent(),
    rhymes: (await page.locator('#rhyme-list').innerText()).split('\n'),
    hitDisabled: await page.locator('#hit-button').isDisabled(),
    pattern: await page.locator('#pattern-rule').textContent(),
    letters: await page.locator('#pattern-strip [data-letter]').allInnerTexts(),
  };
  if (!out.hitDisabled) { await page.locator('#hit-button').click(); await page.waitForTimeout(200); }
  out.toast = await page.locator('#toast').textContent();
  out.streak = await page.locator('#streak-value').textContent();
  return out;
}
JS
playwright-cli run-code --filename /tmp/opencode/final2.js 2>&1 | head -3; playwright-cli console 2>&1 | tail -3; playwright-cli screenshot --filename=screenshots/final-check.jpg 2>&1 | tail -1

